#!/usr/bin/env python3
"""Case classifier with structured output (Anthropic API).

Usage:
  python classifier.py "case text"
  python classifier.py --file case.txt
  cat case.txt | python classifier.py

Requirements:
  pip install anthropic
  export ANTHROPIC_API_KEY="your-key"   (Windows: set ANTHROPIC_API_KEY=...)
"""

import argparse
import json
import os
import sys

try:
    import anthropic
except ImportError:
    sys.exit("Missing the Anthropic SDK. Install it with: pip install anthropic")

# ── Configuration: adapt this to your business ──────────────────────────

MODEL = "claude-haiku-4-5"  # classification is a job for a small, cheap model

CATEGORIES = ["inquiry", "order", "incident", "invoice", "complaint", "other"]
CONFIDENCE_THRESHOLD = 0.7  # below this, the case is flagged for human review
MAX_CHARACTERS = 12000  # ~3,000 words; above this, we warn

SYSTEM = (
    "You are a case classifier for a business, working in English. "
    "Read the text and classify it by calling the tool. "
    "If the text doesn't clearly fit any category, use 'other' "
    "with low confidence. The reason must quote words from the text itself."
)

# The tool with a strict schema: the API guarantees the response
# validates against this schema. No broken JSON, no surprise fields.
TOOL = {
    "name": "classify_case",
    "description": "Records the classification of the analyzed case.",
    "strict": True,
    "input_schema": {
        "type": "object",
        "properties": {
            "category": {"type": "string", "enum": CATEGORIES},
            "urgency": {"type": "string", "enum": ["high", "medium", "low"]},
            "confidence": {
                "type": "number",
                "minimum": 0,
                "maximum": 1,
                "description": "Confidence of the classification, from 0 to 1.",
            },
            "reason": {
                "type": "string",
                "description": "One sentence quoting the text that justifies the category.",
            },
        },
        "required": ["category", "urgency", "confidence", "reason"],
        "additionalProperties": False,
    },
}

# ── Logic ─────────────────────────────────────────────────────────────


def classify(client: "anthropic.Anthropic", text: str) -> dict:
    """Calls the API forcing tool use and returns the resulting dict."""
    response = client.messages.create(
        model=MODEL,
        max_tokens=512,
        system=SYSTEM,
        tools=[TOOL],
        tool_choice={"type": "tool", "name": "classify_case"},
        messages=[{"role": "user", "content": text}],
    )
    for block in response.content:
        if block.type == "tool_use" and block.name == "classify_case":
            return dict(block.input)
    raise RuntimeError("The API did not return the expected classification.")


def read_input(args: argparse.Namespace) -> str:
    if args.file:
        try:
            with open(args.file, encoding="utf-8") as f:
                return f.read()
        except OSError as e:
            sys.exit(f"Can't read the file: {e}")
    if args.text:
        return args.text
    if not sys.stdin.isatty():
        return sys.stdin.read()
    sys.exit("Give me some text: as an argument, with --file, or via stdin. See --help.")


def main() -> None:
    parser = argparse.ArgumentParser(description="Classifies a free-text case.")
    parser.add_argument("text", nargs="?", help="Text of the case to classify")
    parser.add_argument("--file", help="Path to a text file containing the case")
    args = parser.parse_args()

    if not os.environ.get("ANTHROPIC_API_KEY"):
        sys.exit(
            "Missing the ANTHROPIC_API_KEY environment variable.\n"
            "Create the key at console.anthropic.com and export it before running."
        )

    text = read_input(args).strip()
    if not text:
        sys.exit("The text is empty: nothing to classify.")
    if len(text) > MAX_CHARACTERS:
        print(
            f"WARNING: {len(text)} characters; trimming to {MAX_CHARACTERS}.",
            file=sys.stderr,
        )
        text = text[:MAX_CHARACTERS]

    client = anthropic.Anthropic()  # reads ANTHROPIC_API_KEY from the environment

    try:
        result = classify(client, text)
    except anthropic.AuthenticationError:
        sys.exit("Invalid or revoked API key. Check ANTHROPIC_API_KEY.")
    except anthropic.RateLimitError:
        sys.exit("Rate limit reached. Wait a minute and try again.")
    except anthropic.APIStatusError as e:
        sys.exit(f"API error ({e.status_code}): {e.message}")
    except anthropic.APIConnectionError:
        sys.exit("No connection to the API. Check your network and try again.")

    # Confidence brake: anything doubtful is flagged for human review.
    result["needs_human_review"] = result["confidence"] < CONFIDENCE_THRESHOLD

    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
